# Simulate constant error e in single-channel arm
# Nominal volumes from method
steps = {
 'T1': (0,300),
 'T2': (18.75,281.25),
 'T3': (37.5,262.5),
 'T4': (75,225),
 'T5': (112.5,187.5),
 'T6': (150,150),
 'T7': (225,75),
 'T8': (300,0), # only STD
}
nom_conc = {'T1':0,'T2':25,'T3':50,'T4':100,'T5':150,'T6':200,'T7':300,'T8':400}
C_stock=400
def actual(e):
    res={}
    for t,(vs,vd) in steps.items():
        if t=='T1':
            res[t]=0
        elif t=='T8':
            res[t]=C_stock # (vs+e)/(vs+e)
        else:
            res[t]=(vs+e)/(vs+vd+2*e)*C_stock
    return res

for e in [0,2,5,10,-2,-5]:
    a=actual(e)
    print(f"e={e}", {k: round(v,2) for k,v in a.items()})
PY

